## Showing on Hover

```tsx
function HoverPopup() {
  const hovered = useHover();
  const { show, hide } = usePopup();

  useEffect(() => {
    if (hovered) {
      // Get screen position from annotation bounds
      show({ x: 100, y: 100 }, hovered);
    } else {
      hide();
    }
  }, [hovered]);

  // Render popup...
}
```

## Showing on Click

```tsx
function ClickPopup({ viewer }) {
  const { show } = usePopup();
  const annotator = useAnnotator();

  useEffect(() => {
    if (!annotator) return;

    const handleClick = (e) => {
      const point = viewer.viewport.pointFromPixel(e.position);
      const hit = annotator.hitTest(point);
      if (hit) {
        show({ x: e.originalEvent.clientX, y: e.originalEvent.clientY }, hit);
      }
    };

    viewer.addHandler('canvas-click', handleClick);
    return () => viewer.removeHandler('canvas-click', handleClick);
  }, [annotator, viewer]);

  return null;
}
```

