```tsx
import { useAnnotator } from "annota";
import { useEffect } from "react";

function LoadAnnotations() {
  const annotator = useAnnotator();

  useEffect(() => {
    if (!annotator) return;

    fetch("/api/annotations/slide-001")
      .then((res) => res.json())
      .then((annotations) => {
