  </TabItem>
  <TabItem label="Svelte">
    ```svelte
    <script>
      import { tool } from "annota/svelte";
      import { RectangleTool } from "annota";

      let viewer = $state(null);

      const rectTool = $derived(new RectangleTool());

      $effect(() => {
        if (!viewer) return;

        tool({
          viewer: () => viewer,
          handler: () => rectTool,
          enabled: () => true,
