## Component Structure

### Provider Setup

<Tabs>
  <TabItem label="React">
    ```tsx
    import { AnnotaProvider, AnnotaViewer, Annotator } from "annota";

    function App() {
      const [viewer, setViewer] = useState(null);

      return (
        <AnnotaProvider slideId="my-slide">
          <AnnotaViewer onViewerReady={setViewer} />
          <Annotator viewer={viewer} />
        </AnnotaProvider>
      );
    }
    ```
  </TabItem>
  <TabItem label="Svelte">
    ```svelte
    <script>
      import { AnnotaProvider, AnnotaViewer, Annotator } from "annota/svelte";

      let viewer = $state(null);
    </script>

    <AnnotaProvider slideId="my-slide">
      <AnnotaViewer onViewerReady={(v) => viewer = v} />
      {#if viewer}
        <Annotator {viewer} />
      {/if}
    </AnnotaProvider>
    ```
  </TabItem>
</Tabs>

## Syntax Differences

### Conditional Rendering

| React | Svelte |
|-------|--------|
| `{condition && <Component />}` | `{#if condition}<Component />{/if}` |
| `{condition ? <A /> : <B />}` | `{#if condition}<A />{:else}<B />{/if}` |
| `{!condition && <Component />}` | `{#if !condition}<Component />{/if}` |

### Lists

| React | Svelte |
|-------|--------|
| `{items.map(item => <div key={item.id}>{item.name}</div>)}` | `{#each items as item (item.id)}<div>{item.name}</div>{/each}` |
| Use `key` prop for keys | Use `(item.id)` for keys |

### State

| React | Svelte |
|-------|--------|
| `const [state, setState] = useState()` | `let state = $state()` |
| `const memo = useMemo(() => ..., [deps])` | `const memo = $derived(...)` |
| `useEffect(() => ..., [deps])` | `$effect(() => ...)` |
| `useCallback(fn, [deps])` | Function declarations (no deps) |

## Common Patterns

### Loading Annotations on Mount

<Tabs>
  <TabItem label="React">
    ```tsx
    import { useAnnotator } from "annota";
    import { useEffect } from "react";

    function LoadAnnotations({ slideId }) {
      const annotator = useAnnotator();

      useEffect(() => {
        if (!annotator) return;

        fetch(`/api/annotations/${slideId}`)
          .then(res => res.json())
          .then(anns => annotator.addAnnotations(anns));
      }, [annotator, slideId]);

      return null;
    }
    ```
  </TabItem>
  <TabItem label="Svelte">
    ```svelte
    <script>
      import { onMount } from "svelte";
      import { getAnnotator } from "annota/svelte";

      const { slideId } = $props();
      const getAnnotatorFn = getAnnotator();
      const annotator = $derived(getAnnotatorFn());

      onMount(() => {
        if (!$annotator) return;

        fetch(`/api/annotations/${slideId}`)
          .then(res => res.json())
          .then(anns => $annotator.addAnnotations(anns));
      });
    </script>
    ```
  </TabItem>
</Tabs>

